<template><view class="page"><view class="hero"><text class="title">学习中心</text><text class="sub">规划学习路径，记录每一点进步</text></view><text class="section">课程分类</text><view class="course" @click="go('/pages/phonetic/index')"><text class="icon">🔊</text><view><text>音标课程</text><small>48 个英美音标，逐个掌握</small></view><text>›</text></view><view class="course" @click="go('/pages/word/index')"><text class="icon">📚</text><view><text>单词词库</text><small>分类词库，科学记忆</small></view><text>›</text></view><view class="course" @click="go('/pages/grammar/index')"><text class="icon">📝</text><view><text>语法课程</text><small>三阶段语法体系</small></view><text>›</text></view><text class="section">学习进度</text><view class="progress"><view v-for="x in progress" :key="x.name" class="line"><view><text>{{x.name}}</text><b>{{x.label || (x.value + '%')}}</b></view><i><em :style="{width:x.value+'%'}"/></i></view></view></view></template>
<script>import{getWordStatus,request}from'@/utils/api.js';export default{data(){return{phoneticPercent:0,wordPercent:0,grammarPercent:0,wordMastered:0,wordTotal:0,phoneticMastered:0,grammarMastered:0,grammarTotal:0}},computed:{phoneticLabel(){return this.phoneticMastered + '/48（' + this.phoneticPercent + '%）'},grammarLabel(){return this.grammarMastered + '/' + (this.grammarTotal || 40) + '（' + this.grammarPercent + '%）'},wordLabel(){return this.wordTotal ? this.wordMastered + '/' + this.wordTotal + '（' + this.wordPercent.toFixed(2) + '%）' : '0%'},progress(){return[{name:'音标掌握',value:this.phoneticPercent,label:this.phoneticLabel},{name:'单词积累',value:this.wordPercent,label:this.wordLabel},{name:'语法掌握',value:this.grammarPercent,label:this.grammarLabel}]}},onShow(){this.load()},methods:{async load(){try{const[a,b,c,d,e]=await Promise.all([request('/phonetic/progress?userId=1'),getWordStatus(),request('/grammar/progress?userId=1'),request('/grammar-point/list'),request('/words/count?userId=1')]);this.phoneticMastered=Object.values(a||{}).filter(x=>x.mastered).length;this.phoneticPercent=Math.round(this.phoneticMastered/48*100);const t=(e?.stats||[]).reduce((n,x)=>n+Number(x.count||0),0);this.wordMastered=Object.values(b||{}).filter(x=>x.mastered).length;this.wordTotal=t;this.wordPercent=t?Number((this.wordMastered/t*100).toFixed(2)):0;this.grammarPercent=d?.length?Math.round(Object.values(c||{}).filter(x=>x.status==='已学习').length/d.length*100):0}catch(e){}},go(url){uni.navigateTo({url})}}}</script>
<style>.page{min-height:100vh;padding:34rpx 24rpx;background:#f7f5f0}.hero{padding:15rpx 8rpx 25rpx}.title{display:block;font-size:46rpx;font-weight:800;color:#183e69}.sub{display:block;font-size:25rpx;color:#96a2b0;margin-top:10rpx}.section{display:block;color:#234a75;font-size:32rpx;font-weight:700;margin:26rpx 0 15rpx}.course{display:flex;align-items:center;gap:20rpx;background:#fff;border-radius:20rpx;padding:25rpx;margin:14rpx 0;color:#294b74;font-size:31rpx;font-weight:700;box-shadow:0 5rpx 16rpx rgba(22,59,102,.06)}.course view{flex:1}.course small{display:block;font-size:24rpx;color:#9aa6b5;font-weight:400;margin-top:7rpx}.icon{background:#e9f7f6;border-radius:17rpx;padding:13rpx;font-size:34rpx}.progress{background:#fff;border-radius:20rpx;padding:28rpx;box-shadow:0 5rpx 16rpx rgba(22,59,102,.06)}.line{margin-bottom:27rpx}.line:last-child{margin:0}.line view{display:flex;justify-content:space-between;color:#486482;font-size:28rpx}.line b{color:#0d9488}.line i{display:block;background:#edf1f4;height:14rpx;border-radius:20rpx;margin-top:13rpx;overflow:hidden}.line em{display:block;height:100%;background:linear-gradient(90deg,#20c6b5,#0d9488);border-radius:20rpx}</style>
